import logging
import test
from builtins import str


logger = logging.getLogger(__name__)


# Simplified show message box using built in WinAPI
# The box is set to have 'OK' button,set to modal to interrupt work till acknowledged
# And set to come into foreground when launched
# All details can be found here https://docs.microsoft.com/en-us/windows/desktop/api/winuser/nf-winuser-messageboxa
def showMsg(title, message, timeout=-1):
    stop_execution = 0x00000000  # Stops execution till message is acknowledged
    information_icon = 0x00000040  # Creates information icon in windows box
    set_foreground_window = 0x00010000  # Sets the message box to foreground
    import ctypes
    ctypes.windll.user32.MessageBoxW(0, message, title, stop_execution | information_icon | set_foreground_window)


def show_html_dialog(html_path, height=None, width=None, options=None):
    #      Display an Html dialog to the user.
    #
    #         Args: html_path (str): location the html file to display in dialog
    #               height(int): Height of the dialog window (optional)
    #               width(int): width of the dialog window (optional)
    #               options(str): comma separated value-pairs (optional)
    #        Return:  String representation of window.returnValue from dialog box.

    import os
    import sys
    from interops.libraries.desktop.configuration import Config
    import interops.libraries.desktop.config_constants as cfg

    # Get the current python installation path
    python_install_path = sys.exec_prefix
    sharedconfig_path = os.path.abspath(os.path.join(
        python_install_path, cfg.DEFAULT_SHAREDCONFIG_PATH))
    # Load the sharedconfig.cfg file
    Config.load(sharedconfig_path)

    comtypes_path = Config.get("Python.comtypes_path")
    logger.debug("comtypes_path: " + comtypes_path)
    try:
        from comtypes import IUnknown
    except ImportError:
        sys.path.insert(0, comtypes_path)
        import comtypes

    from ctypes import windll
    from ctypes import byref
    from ctypes import POINTER
    from comtypes import IUnknown
    from comtypes.automation import VARIANT

    url = os.path.abspath(html_path)
    logger.info("loading Html dialog source: " + url)

    DEFAULT_OPTIONS = "center:yes;resizable:yes;scroll:yes;"

    if options is None:
        options = DEFAULT_OPTIONS
    if width is not None:
        options = options + "dialogWidth:" + str(width) + "px;"
    if height is not None:
        options = options + "dialogHeight:" + str(height) + "px;"

    print(options)

    URL_MK_UNIFORM = 1
    url_moniker = POINTER(IUnknown)()
    try:
        windll.urlmon.CreateURLMonikerEx(0, str(url), byref(url_moniker), URL_MK_UNIFORM)
    except Exception as e:
        test.log("WinDLL error " + str(e))  # type: ignore

#     HRESULT ShowHTMLDialog(
#        HWND           hwndParent,
#        IMoniker       *pMk,
#        VARIANT        *pvarArgIn,
#        _In_ LPWSTR    pchOptions,
#        VARIANT  *pvarArgOut
#     );
#
#     hwndParent - A handle to the parent of the dialog box.
#     pMk - The address of an IMoniker interface from which the HTML for the dialog box is loaded.
#
#     pvarArgIn - The address of a VARIANT structure that contains the input data for the dialog box.
#                 The data passed in this VARIANT is placed in the window object's IHTMLDialog::dialogArguments property.
#                 This parameter can be NULL.
#
#     pchOptions [in] - The window ornaments for the dialog box.
#                       This parameter can be NULL or the address of a string that contains a combination of values separated
#                       by semicolons (;).
#                       See the description of the features parameter of the IHTMLWindow2::showModalDialog method of the window
#                       object for detailed information.
#
#     pvarArgOut - The address of a VARIANT structure that contains the output data for the dialog box. This VARIANT receives
#                  the data that was placed in the window object's IHTMLDialog::returnValue property. This parameter can be NULL.
#
#     Return value - If this function succeeds, it returns S_OK. Otherwise, it returns an HRESULT error code.

    argOut = VARIANT()
    uc_options = str(options)
    windll.mshtml.ShowHTMLDialog(None, url_moniker, None, str(options), byref(argOut))
    retval = ""
    try:
        retval = argOut[0]
    except Exception as e:
        pass
    if retval is None:
        retval = ""
    return retval
